using System.Security.Claims; using AshkanCMS.Data; using AshkanCMS.Models; using Microsoft.AspNetCore.Authentication; using Microsoft.AspNetCore.Authentication.Cookies; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AshkanCMS.Controllers;
public class AccountController(AppDbContext db,IPasswordHasher<CmsUser> hasher):Controller {
 private bool Fa => Request.Cookies["ashkan.lang"]=="fa";
 [HttpGet] public IActionResult Login(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View(new LoginVm());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginVm vm,string? returnUrl=null){if(!ModelState.IsValid)return View(vm);var u=await db.Users.FirstOrDefaultAsync(x=>x.UserName==vm.UserName&&x.IsActive);if(u==null||hasher.VerifyHashedPassword(u,u.PasswordHash,vm.Password)==PasswordVerificationResult.Failed){db.LoginEvents.Add(new LoginEvent{UserName=vm.UserName,Success=false,IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()??"",UserAgent=Request.Headers.UserAgent.ToString()});await db.SaveChangesAsync();ModelState.AddModelError("",Fa?"نام کاربری یا رمز عبور صحیح نیست.":"Invalid username or password.");return View(vm);}db.LoginEvents.Add(new LoginEvent{UserName=u.UserName,Success=true,IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()??"",UserAgent=Request.Headers.UserAgent.ToString()});await db.SaveChangesAsync();var claims=new[]{new Claim(ClaimTypes.Name,u.DisplayName),new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Role,u.Role)};await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme)),new AuthenticationProperties{IsPersistent=vm.RememberMe});return LocalRedirect(string.IsNullOrWhiteSpace(returnUrl)?"/Admin":returnUrl);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync();return RedirectToAction(nameof(Login));} public IActionResult Denied()=>View(); }
